from pysat.solvers import Solver
from pysat.formula import CNF

# 16x16 Sudoku solver
# Variables: v(r, c, d) = True if cell (r,c) has digit d
# r, c, d are 0-indexed (0-15)

def var(r, c, d):
    return r * 16 * 16 + c * 16 + d + 1  # 1-indexed

cnf = CNF()

# Each cell has at least one digit
for r in range(16):
    for c in range(16):
        cnf.append([var(r, c, d) for d in range(16)])

# Each cell has at most one digit
for r in range(16):
    for c in range(16):
        for d1 in range(16):
            for d2 in range(d1+1, 16):
                cnf.append([-var(r, c, d1), -var(r, c, d2)])

# Each row contains each digit exactly once
for r in range(16):
    for d in range(16):
        cnf.append([var(r, c, d) for c in range(16)])
        for c1 in range(16):
            for c2 in range(c1+1, 16):
                cnf.append([-var(r, c1, d), -var(r, c2, d)])

# Each column contains each digit exactly once
for c in range(16):
    for d in range(16):
        cnf.append([var(r, c, d) for r in range(16)])
        for r1 in range(16):
            for r2 in range(r1+1, 16):
                cnf.append([-var(r1, c, d), -var(r2, c, d)])

# Each 4x4 block contains each digit exactly once
for br in range(4):
    for bc in range(4):
        cells = [(br*4+i, bc*4+j) for i in range(4) for j in range(4)]
        for d in range(16):
            cnf.append([var(r, c, d) for r, c in cells])
            for i1 in range(len(cells)):
                for i2 in range(i1+1, len(cells)):
                    r1, c1 = cells[i1]
                    r2, c2 = cells[i2]
                    cnf.append([-var(r1, c1, d), -var(r2, c2, d)])

# Fixed assignments (0-indexed positions, 1-indexed values)
fixed = {
    5: 6, 13: 14, 14: 15, 18: 7, 22: 3, 26: 15, 27: 16,
    33: 10, 34: 11, 42: 3, 53: 10, 54: 11, 57: 6, 58: 7,
    69: 5, 71: 7, 80: 6, 81: 5, 83: 7, 84: 2, 85: 1,
    94: 12, 103: 15, 106: 4, 107: 3, 109: 5, 112: 14,
    115: 15, 120: 6, 135: 6, 136: 11, 140: 15, 141: 16,
    148: 3, 150: 1, 170: 1, 175: 6, 185: 8, 188: 3,
    190: 1, 196: 8, 199: 5, 201: 11, 203: 9, 208: 8,
    218: 14, 240: 16, 241: 15, 243: 13, 244: 12, 253: 3
}

for pos, val in fixed.items():
    r = pos // 16
    c = pos % 16
    d = val - 1  # 0-indexed digit
    cnf.append([var(r, c, d)])

print(f"CNF has {cnf.nv} variables and {len(cnf.clauses)} clauses")

solver = Solver(name='cd', bootstrap_with=cnf)
result = solver.solve()
print(f"Satisfiable: {result}")

if result:
    model = solver.get_model()
    grid = [0] * 256
    for r in range(16):
        for c in range(16):
            for d in range(16):
                if model[var(r, c, d) - 1] > 0:
                    grid[r * 16 + c] = d + 1
    print("Solution found!")
    print(grid)

    # Verify
    valid = True
    for r in range(16):
        row = [grid[r*16+c] for c in range(16)]
        if sorted(row) != list(range(1,17)):
            print(f"Row {r} invalid: {row}")
            valid = False
    for c in range(16):
        col = [grid[r*16+c] for r in range(16)]
        if sorted(col) != list(range(1,17)):
            print(f"Col {c} invalid: {col}")
            valid = False
    for br in range(4):
        for bc in range(4):
            block = [grid[(br*4+i)*16+(bc*4+j)] for i in range(4) for j in range(4)]
            if sorted(block) != list(range(1,17)):
                print(f"Block ({br},{bc}) invalid: {block}")
                valid = False
    for pos, val in fixed.items():
        if grid[pos] != val:
            print(f"Fixed value mismatch at {pos}: expected {val}, got {grid[pos]}")
            valid = False
    print(f"Valid: {valid}")
